-- Generated by scripts/generate-codex-cost-schema.mjs.
-- Run once per shard with bound backfillFrom/backfillTo; at most one day per invocation.
-- Repeatable, including overlaps with live MVs. Does not activate the read path.
SELECT throwIf({backfillTo:DateTime('UTC')} <= {backfillFrom:DateTime('UTC')}
  OR dateDiff('second', {backfillFrom:DateTime('UTC')}, {backfillTo:DateTime('UTC')}) > 86400,
  'Codex cost backfill requires a positive interval of at most one day');

INSERT INTO claude_code.codex_cost_events_v1 (Timestamp, Identity, UserEmail, ConversationId, Model, Backend, ProjectName, EventName, Kind, Rejected, InputValue, InputValid, CacheReadValue, CacheReadValid, CacheWriteValue, CacheWriteValid, OutputValue, OutputValid, ReasoningValue, ReasoningValid)
SELECT Timestamp,
  toJSONString(tuple(mapSort(ResourceAttributes),mapSort(LogAttributes))) AS Identity,
  coalesce(nullIf(ResourceAttributes['user.email'], ''),
    nullIf(ResourceAttributes['enduser.id'], ''), '') AS UserEmail,
  LogAttributes['conversation.id'] AS ConversationId, LogAttributes['model'] AS Model,
  multiIf(match(LogAttributes['model'], '^(us|us-gov|eu|apac|jp|au|in|global)\\.'), 'bedrock-runtime',
    match(LogAttributes['model'], '^[a-z][a-z0-9-]*[a-z]\\.'), 'bedrock-mantle',
    ResourceAttributes['backend'] IN ('bedrock-mantle','bedrock-runtime'), ResourceAttributes['backend'], 'unknown') AS Backend,
  ResourceAttributes['project.name'] AS ProjectName, EventName, multiIf(
  EventName IN ('codex.sse_event','codex.websocket_event') AND LogAttributes['event.kind'] = 'response.completed'
    AND hasAny(mapKeys(LogAttributes), ['input_token_count','cached_token_count','cache_write_token_count','output_token_count','reasoning_token_count']), 'usage',
  EventName IN ('codex.sse_event','codex.websocket_event') AND LogAttributes['event.kind'] = 'response.completed', 'completion',
  EventName IN ('codex.sse_event','codex.websocket_event') AND LogAttributes['event.kind'] = 'response.failed', 'stream_error',
  EventName IN ('codex.sse_event','codex.websocket_event'), 'scope_evidence',
  EventName IN ('codex.api_request','codex.api_error'), 'request',
  EventName = 'codex.tool_result', 'tool',
  EventName = 'codex.tool_decision', 'approval',
  EventName = 'codex.turn_ttft', 'ttft',
  NOT has(['codex.conversation_starts','codex.startup_phase','codex.user_prompt'], EventName) OR hasAny(mapKeys(LogAttributes), ['input_token_count','output_token_count','cached_token_count','cache_write_token_count','reasoning_token_count','tool_token_count']), 'scope_evidence', '') AS Kind,
  toUInt8(EventName IN ('codex.api_request','codex.api_error')
    AND has(['400','401','403','404','413','415','422','429'], trimBoth(LogAttributes['http.response.status_code']))
    AND NOT hasAny(mapKeys(LogAttributes), ['input_token_count','output_token_count','cached_token_count','cache_write_token_count','reasoning_token_count','tool_token_count'])) AS Rejected,
  toFloat64OrZero(LogAttributes['input_token_count']) AS InputValue,
  toUInt8(mapContains(LogAttributes,'input_token_count')
    AND isNotNull(toFloat64OrNull(LogAttributes['input_token_count']))
    AND isFinite(InputValue) AND InputValue >= 0
    AND floor(InputValue) = InputValue AND InputValue <= 9007199254740991) AS InputValid,
  toFloat64OrZero(LogAttributes['cached_token_count']) AS CacheReadValue,
  toUInt8(mapContains(LogAttributes,'cached_token_count')
    AND isNotNull(toFloat64OrNull(LogAttributes['cached_token_count']))
    AND isFinite(CacheReadValue) AND CacheReadValue >= 0
    AND floor(CacheReadValue) = CacheReadValue AND CacheReadValue <= 9007199254740991) AS CacheReadValid,
  toFloat64OrZero(LogAttributes['cache_write_token_count']) AS CacheWriteValue,
  toUInt8(mapContains(LogAttributes,'cache_write_token_count')
    AND isNotNull(toFloat64OrNull(LogAttributes['cache_write_token_count']))
    AND isFinite(CacheWriteValue) AND CacheWriteValue >= 0
    AND floor(CacheWriteValue) = CacheWriteValue AND CacheWriteValue <= 9007199254740991) AS CacheWriteValid,
  toFloat64OrZero(LogAttributes['output_token_count']) AS OutputValue,
  toUInt8(mapContains(LogAttributes,'output_token_count')
    AND isNotNull(toFloat64OrNull(LogAttributes['output_token_count']))
    AND isFinite(OutputValue) AND OutputValue >= 0
    AND floor(OutputValue) = OutputValue AND OutputValue <= 9007199254740991) AS OutputValid,
  toFloat64OrZero(LogAttributes['reasoning_token_count']) AS ReasoningValue,
  toUInt8(mapContains(LogAttributes,'reasoning_token_count')
    AND isNotNull(toFloat64OrNull(LogAttributes['reasoning_token_count']))
    AND isFinite(ReasoningValue) AND ReasoningValue >= 0
    AND floor(ReasoningValue) = ReasoningValue AND ReasoningValue <= 9007199254740991) AS ReasoningValid
  FROM claude_code.otel_logs
  WHERE startsWith(EventName, 'codex.') AND (Timestamp >= {backfillFrom:DateTime('UTC')} AND Timestamp < {backfillTo:DateTime('UTC')}) AND Kind NOT IN ('','scope_evidence');

INSERT INTO claude_code.codex_cost_scope_v1 (Minute, UserEmail, ConversationId, Model, Backend, ProjectName, EventName, Seconds)
SELECT toStartOfMinute(Timestamp) AS Minute, coalesce(nullIf(ResourceAttributes['user.email'], ''),
    nullIf(ResourceAttributes['enduser.id'], ''), '') AS UserEmail,
  LogAttributes['conversation.id'] AS ConversationId, LogAttributes['model'] AS Model,
  multiIf(match(LogAttributes['model'], '^(us|us-gov|eu|apac|jp|au|in|global)\\.'), 'bedrock-runtime',
    match(LogAttributes['model'], '^[a-z][a-z0-9-]*[a-z]\\.'), 'bedrock-mantle',
    ResourceAttributes['backend'] IN ('bedrock-mantle','bedrock-runtime'), ResourceAttributes['backend'], 'unknown') AS Backend,
  ResourceAttributes['project.name'] AS ProjectName, EventName,
  groupUniqArrayState(toUInt8(toSecond(Timestamp))) AS Seconds
  FROM claude_code.otel_logs
  WHERE startsWith(EventName, 'codex.') AND (Timestamp >= {backfillFrom:DateTime('UTC')} AND Timestamp < {backfillTo:DateTime('UTC')}) AND (multiIf(
  EventName IN ('codex.sse_event','codex.websocket_event') AND LogAttributes['event.kind'] = 'response.completed'
    AND hasAny(mapKeys(LogAttributes), ['input_token_count','cached_token_count','cache_write_token_count','output_token_count','reasoning_token_count']), 'usage',
  EventName IN ('codex.sse_event','codex.websocket_event') AND LogAttributes['event.kind'] = 'response.completed', 'completion',
  EventName IN ('codex.sse_event','codex.websocket_event') AND LogAttributes['event.kind'] = 'response.failed', 'stream_error',
  EventName IN ('codex.sse_event','codex.websocket_event'), 'scope_evidence',
  EventName IN ('codex.api_request','codex.api_error'), 'request',
  EventName = 'codex.tool_result', 'tool',
  EventName = 'codex.tool_decision', 'approval',
  EventName = 'codex.turn_ttft', 'ttft',
  NOT has(['codex.conversation_starts','codex.startup_phase','codex.user_prompt'], EventName) OR hasAny(mapKeys(LogAttributes), ['input_token_count','output_token_count','cached_token_count','cache_write_token_count','reasoning_token_count','tool_token_count']), 'scope_evidence', '')) = 'scope_evidence'
  GROUP BY Minute, UserEmail, ConversationId, Model, Backend, ProjectName, EventName;
